# Update Base Template: Browser Notification Permission
# Run from your dashboard folder (where manage.py is)

$base64 = ""
$bytes = [System.Convert]::FromBase64String($base64)
$py = [System.Text.Encoding]::UTF8.GetString($bytes)

# Backup
$ts = Get-Date -Format "yyyyMMdd_HHmmss"
Copy-Item -Path "templates\base.html" -Destination "templates\base.html.backup.$ts" -ErrorAction SilentlyContinue

# Write and run Python script
[IO.File]::WriteAllText("_temp_base.py", $py)
python "_temp_base.py"
Remove-Item "_temp_base.py"

Write-Host "✅ Done! base.html updated with notification permission request" -ForegroundColor Green
